<form class="form-card wide-form" method="POST" action="{{ $formAction }}"><input type="hidden" name="_token" value="{{ csrf_token() }}"><input type="hidden" name="_method" value="{{ $formMethod }}"><div class="form-grid"><label>Product name<input type="text" name="name" value="{{ old('name', $product?->name) }}" required></label><label>Category<select name="category_id" required><option value="">Choose category</option>@foreach($categories as $category)<option value="{{ $category->id }}" @selected(old('category_id', $product?->category_id) == $category->id)>{{ $category->name }}</option>@endforeach</select></label><label>Price<input type="number" name="price" step="0.01" min="0" value="{{ old('price', $product?->price) }}" required></label><label>Size<input type="text" name="size" value="{{ old('size', $product?->size) }}" placeholder="S, M, L" required></label><label>Color<input type="text" name="color" value="{{ old('color', $product?->color) }}" required></label><label>Stock<input type="number" name="stock" min="0" value="{{ old('stock', $product?->stock ?? 0) }}" required></label></div><label>Description<textarea name="description" rows="5" required>{{ old('description', $product?->description) }}</textarea></label><label>Image URL <span class="muted">(optional)</span><input type="url" name="image_url" value="{{ old('image_url', $product?->image_url) }}"></label><button class="button" type="submit">{{ $product ? 'Save changes' : 'Publish product' }}</button></form>
